import os,json
exec(open('gen3.py').read().split('P={}')[0])
P={}
W='smartschool360.co.in'
# L1 Swiss typographic: exam modes
row=lambda k,t,d,on: f'<div style="display:flex;align-items:center;gap:40px;padding:22px 40px;border-top:3px solid var(--ink);{"background:var(--ink);color:#F4F3EE" if on else ""}"><div style="font:900 96px/0.85 Inter Tight;letter-spacing:-4px;width:200px;{"color:var(--lime)" if on else ""}">{k}</div><div><div style="font:800 46px Inter Tight;letter-spacing:-1px">{t}</div><div style="font:500 28px Inter Tight;margin-top:8px;color:{"#A9AAA3" if on else "var(--mute)"}">{d}</div></div></div>'
P['l7-naac-v2']=[pg(hd()+'<div class=abs style="left:80px;top:190px;font:900 96px/0.95 Inter Tight;letter-spacing:-5px">NAAC visit<br>coming up?</div>'+'<div class=abs style="right:70px;top:170px;width:380px;height:280px;display:flex;align-items:center;justify-content:center"><img src=product.png style="width:430px;border-radius:24px"></div>'+'<div class=abs style="left:80px;right:80px;top:470px;font:500 32px/1.35 Inter Tight;color:var(--mute)">One installation. Evidence assessors can see.</div>'+'<div class=abs style="left:80px;right:80px;top:560px;display:grid;grid-template-columns:1fr 1fr;gap:24px">'+'<div style="padding:34px 36px;border-radius:28px;background:#fff"><div style="font:900 110px/0.85 Inter Tight;letter-spacing:-5px;color:#0B0C0A">C2</div><div style="font:800 38px Inter Tight;letter-spacing:-1px;margin-top:22px">Teaching-learning</div><div style="font:500 24px/1.35 Inter Tight;margin-top:8px;color:#6b6d66">Every period on time. Prayer and anthem automated.</div></div><div style="padding:34px 36px;border-radius:28px;background:#0B0C0A;color:#F4F3EE"><div style="font:900 110px/0.85 Inter Tight;letter-spacing:-5px;color:#A3CF44">C4</div><div style="font:800 38px Inter Tight;letter-spacing:-1px;margin-top:22px">Infrastructure</div><div style="font:500 24px/1.35 Inter Tight;margin-top:8px;color:#A9AAA3">Campus PA, zone audio, emergency siren.</div></div><div style="padding:34px 36px;border-radius:28px;background:#0B0C0A;color:#F4F3EE"><div style="font:900 110px/0.85 Inter Tight;letter-spacing:-5px;color:#A3CF44">C6</div><div style="font:800 38px Inter Tight;letter-spacing:-1px;margin-top:22px">Governance</div><div style="font:500 24px/1.35 Inter Tight;margin-top:8px;color:#A9AAA3">ICT scheduling, internet time sync.</div></div><div style="padding:34px 36px;border-radius:28px;background:#fff"><div style="font:900 110px/0.85 Inter Tight;letter-spacing:-5px;color:#0B0C0A">C7</div><div style="font:800 38px Inter Tight;letter-spacing:-1px;margin-top:22px">Best practices</div><div style="font:500 24px/1.35 Inter Tight;margin-top:8px;color:#6b6d66">Water bell, siren drills, punctuality.</div></div>'+'</div>'+ft('Free online demo',W,'color:var(--mute)'),bg='background:var(--paper)')]
manifest={}
for post,slides in P.items():
    os.makedirs(f'out/{post}',exist_ok=True); manifest[post]=[]
    for k,html in enumerate(slides,1):
        name='post'; open(f'{name}__{post}.html','w').write(html); manifest[post].append(name)
json.dump(manifest,open('manifest.json','w'))
